param(
    [string]$ProjectRoot = (Get-Location).Path,
    [string]$OutputPath = (Join-Path (Get-Location).Path "chatgpt-advisory.md"),
    [string]$BackupScriptPath = (Join-Path (Get-Location).Path "backup.ps1"),
    [switch]$IncludeSensitiveDetails,
    [int64]$LargeThresholdMB = 256
)

$ErrorActionPreference = "Stop"

# Preference mining script generated by ChatGPT.
# Goal: inspect likely user-defined preference/config locations and produce
# chatgpt-advisory.md without copying files and without printing secrets.
#
# It classifies candidate paths as:
# - AlreadyCovered: appears in backup.ps1
# - Found: exists on this computer
# - Sensitive: likely contains credentials/tokens/private keys
# - Large: larger than LargeThresholdMB
#
# It intentionally favors metadata and filenames over file contents.

function Expand-CandidatePath {
    param([Parameter(Mandatory)][string]$Path)
    [Environment]::ExpandEnvironmentVariables($Path)
}

function ConvertTo-MarkdownSafe {
    param([AllowNull()][string]$Text)
    if ($null -eq $Text) { return "" }
    return ($Text -replace '\|', '\|' -replace "`r?`n", " ")
}

function Get-DirectorySize {
    param([Parameter(Mandatory)][string]$Path)
    try {
        if (-not (Test-Path -LiteralPath $Path)) { return 0 }
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if (-not $item.PSIsContainer) { return [int64]$item.Length }

        $sum = 0L
        Get-ChildItem -LiteralPath $Path -Recurse -Force -ErrorAction SilentlyContinue |
            Where-Object { -not $_.PSIsContainer } |
            ForEach-Object { $sum += [int64]$_.Length }
        return $sum
    }
    catch {
        return $null
    }
}

function Format-Bytes {
    param([AllowNull()][Nullable[int64]]$Bytes)
    if ($null -eq $Bytes) { return "unknown" }
    if ($Bytes -ge 1GB) { return ("{0:N2} GB" -f ($Bytes / 1GB)) }
    if ($Bytes -ge 1MB) { return ("{0:N2} MB" -f ($Bytes / 1MB)) }
    if ($Bytes -ge 1KB) { return ("{0:N2} KB" -f ($Bytes / 1KB)) }
    return "$Bytes B"
}

function Get-InterestingChildren {
    param(
        [Parameter(Mandatory)][string]$Path,
        [int]$Limit = 30
    )

    if (-not (Test-Path -LiteralPath $Path)) { return @() }

    $noise = @(
        'cache','caches','Cache','GPUCache','Code Cache','CachedData','logs','log','tmp','temp',
        'crashpad','Crashpad','crashes','Crash Reports','updates','blob_storage','Service Worker',
        'DawnCache','ShaderCache','GrShaderCache','__pycache__','node_modules','.git'
    )

    try {
        $item = Get-Item -LiteralPath $Path -Force
        if (-not $item.PSIsContainer) {
            return @($item.Name)
        }

        return @(Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue |
            Where-Object { $noise -notcontains $_.Name } |
            Sort-Object LastWriteTime -Descending |
            Select-Object -First $Limit |
            ForEach-Object {
                if ($_.PSIsContainer) { "$($_.Name)/" } else { $_.Name }
            })
    }
    catch {
        return @()
    }
}

function Read-BackupCoveredPaths {
    param([string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) { return @{} }

    $text = Get-Content -LiteralPath $Path -Raw
    $matches = [regex]::Matches($text, '["''](%[^"'']+)["'']')
    $map = @{}
    foreach ($m in $matches) {
        $raw = $m.Groups[1].Value
        $expanded = (Expand-CandidatePath $raw).TrimEnd('\')
        $map[$expanded.ToLowerInvariant()] = $raw
    }
    return $map
}

function New-Candidate {
    param(
        [Parameter(Mandatory)][string]$Category,
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Why,
        [ValidateSet("Add","Consider","InventoryOnly","AlreadyCovered","Avoid","Manual")]
        [string]$Recommendation = "Consider",
        [bool]$Sensitive = $false,
        [string]$RestoreNote = "",
        [string]$EvidenceHint = ""
    )

    [pscustomobject]@{
        Category = $Category
        Name = $Name
        Path = $Path
        Why = $Why
        Recommendation = $Recommendation
        Sensitive = $Sensitive
        RestoreNote = $RestoreNote
        EvidenceHint = $EvidenceHint
    }
}

$covered = Read-BackupCoveredPaths -Path $BackupScriptPath

