    New-Candidate "Shells and terminals" "Windows Terminal Preview settings" "%LOCALAPPDATA%\Packages\Microsoft.WindowsTerminalPreview_8wekyb3d8bbwe\LocalState\settings.json" "Preview terminal profiles/settings, if used." "Consider" $false
    New-Candidate "Shells and terminals" "Oh My Posh themes/config" "%USERPROFILE%\.poshthemes" "Custom prompt themes, if not only installed defaults." "Consider" $false
    New-Candidate "Shells and terminals" "Bash rc" "%USERPROFILE%\.bashrc" "User-defined shell initialization." "AlreadyCovered" $false
    New-Candidate "Shells and terminals" "WSL global config" "%USERPROFILE%\.wslconfig" "Global WSL limits/network/systemd behavior." "AlreadyCovered" $false

    # VS Code / AI tools
    New-Candidate "Editors and AI assistants" "VS Code user settings" "%APPDATA%\Code\User\settings.json" "Explicit editor settings." "AlreadyCovered" $false
    New-Candidate "Editors and AI assistants" "VS Code keybindings" "%APPDATA%\Code\User\keybindings.json" "Explicit keyboard customizations." "AlreadyCovered" $false
    New-Candidate "Editors and AI assistants" "VS Code snippets" "%APPDATA%\Code\User\snippets" "Hand-written snippets." "AlreadyCovered" $false
    New-Candidate "Editors and AI assistants" "VS Code Copilot memory" "%APPDATA%\Code\User\globalStorage\github.copilot-chat\memory-tool\memories" "Copilot memory/preferences." "AlreadyCovered" $false
    New-Candidate "Editors and AI assistants" "VS Code extension inventory" "%USERPROFILE%\dev-setup\vscode-extensions.txt" "Small explicit extension list generated by code --list-extensions." "Add" $false "Generate during backup, do not copy extension binaries."
    New-Candidate "Editors and AI assistants" "VS Code profile definitions" "%APPDATA%\Code\User\profiles" "Named VS Code profiles, if used." "Add" $false
