    New-Candidate "Language tooling" "npm config" "%USERPROFILE%\.npmrc" "NPM registry/token config." "AlreadyCovered" $true
    New-Candidate "Language tooling" "NuGet config" "%APPDATA%\NuGet\NuGet.Config" ".NET package source configuration; may contain tokens." "Add" $true
    New-Candidate "Language tooling" "Cargo config" "%USERPROFILE%\.cargo\config.toml" "Rust registry/build config if present." "Consider" $false

    # Cloud/remote
    New-Candidate "Cloud and remote CLIs" "GitHub CLI" "%USERPROFILE%\.config\gh" "GitHub hosts, auth, aliases." "Add" $true
    New-Candidate "Cloud and remote CLIs" "AWS CLI" "%USERPROFILE%\.aws" "AWS profiles/credentials." "AlreadyCovered" $true
