    New-Candidate "Cloud and remote CLIs" "OpenVPN app config" "%APPDATA%\OpenVPN Connect" "VPN profiles/app state; likely sensitive." "Consider" $true

    # Containers/VMs/databases
    New-Candidate "Containers and virtualization" "Docker client config" "%USERPROFILE%\.docker" "Docker CLI config/auth/contexts." "AlreadyCovered" $true
    New-Candidate "Containers and virtualization" "Docker Desktop app data" "%APPDATA%\Docker" "Often cache/state-heavy; usually avoid unless specific settings matter." "Avoid" $true
    New-Candidate "Containers and virtualization" "Docker Desktop local data" "%LOCALAPPDATA%\Docker" "Usually large internal VM/state/cache; avoid for preference-only backups." "Avoid" $true
