    New-Candidate "Containers and virtualization" "DBeaver data" "%APPDATA%\DBeaverData" "Database connections, drivers, workspace metadata." "AlreadyCovered" $true
    New-Candidate "Containers and virtualization" "PostgreSQL roaming config" "%APPDATA%\postgresql" "psql history/passfile/certs if present." "Add" $true
    New-Candidate "Containers and virtualization" "psql passfile" "%APPDATA%\postgresql\pgpass.conf" "PostgreSQL saved passwords." "Add" $true

    # Sync/storage tools
    New-Candidate "Sync and storage" "Syncthing local state" "%LOCALAPPDATA%\Syncthing" "Syncthing config/device/folder IDs." "AlreadyCovered" $true
    New-Candidate "Sync and storage" "SyncTrayzor config" "%APPDATA%\SyncTrayzor\config.xml" "SyncTrayzor UI/service settings." "AlreadyCovered" $false
    New-Candidate "Sync and storage" "Synology Drive settings" "%LOCALAPPDATA%\SynologyDrive" "May contain sync task definitions; can be medium/large." "Consider" $true
    New-Candidate "Sync and storage" "Google DriveFS settings" "%LOCALAPPDATA%\Google\DriveFS" "Account/mount metadata. Usually not needed, but may speed restore." "Manual" $true
    New-Candidate "Sync and storage" "OneDrive settings" "%LOCALAPPDATA%\Microsoft\OneDrive\settings" "Account/sync state. Usually reconstructable; settings may help." "Manual" $true

    # Apps installed in your list
    New-Candidate "Applications" "Everything settings" "%APPDATA%\Everything" "Search indexes/settings; current backup covers roaming path." "AlreadyCovered" $false
    New-Candidate "Applications" "Everything service/program data" "%ProgramData%\Everything" "Everything service config/database may live here." "Consider" $false
    New-Candidate "Applications" "FastCopy settings" "%APPDATA%\FastCopy" "Copy presets/preferences." "AlreadyCovered" $false
    New-Candidate "Applications" "WinMerge settings" "%APPDATA%\WinMerge" "Diff tool preferences." "AlreadyCovered" $false
    New-Candidate "Applications" "KDiff3 config" "%USERPROFILE%\.kdiff3rc" "3-way merge tool config." "AlreadyCovered" $false
    New-Candidate "Applications" "Diffuse config" "%USERPROFILE%\.config\diffuse" "N-way diff tool config." "AlreadyCovered" $false
    New-Candidate "Applications" "SumatraPDF settings" "%APPDATA%\SumatraPDF" "Reader preferences and history." "AlreadyCovered" $false
    New-Candidate "Applications" "IrfanView settings" "%APPDATA%\IrfanView" "Viewer preferences/plugins configuration." "AlreadyCovered" $false
    New-Candidate "Applications" "OBS Studio" "%APPDATA%\obs-studio" "Scenes, profiles, plugin config." "AlreadyCovered" $false
    New-Candidate "Applications" "qBittorrent selected config" "%APPDATA%\qBittorrent" "Preferences/categories/watched folders. Avoid BT_backup if not desired." "AlreadyCovered" $false
    New-Candidate "Applications" "Jackett config" "%ProgramData%\Jackett" "Indexer configuration; may contain API keys." "Consider" $true
    New-Candidate "Applications" "yt-dlp config" "%APPDATA%\yt-dlp" "Downloader config if present." "Consider" $false
    New-Candidate "Applications" "gallery-dl config" "%APPDATA%\gallery-dl" "Downloader config; may contain cookies/tokens." "Consider" $true
    New-Candidate "Applications" "Wireshark profile/preferences" "%APPDATA%\Wireshark" "Capture/display profiles and protocol preferences." "Add" $false
    New-Candidate "Applications" "Fiddler settings" "%USERPROFILE%\Documents\Fiddler2" "Rules/certs/captures. Captures may be sensitive/large." "Manual" $true
    New-Candidate "Applications" "Postman data" "%APPDATA%\Postman" "Collections/workspaces/auth if not cloud-synced; can be large." "AlreadyCovered" $true
    New-Candidate "Applications" "WinAuth" "%APPDATA%\WinAuth" "2FA authenticators. Critical and sensitive." "AlreadyCovered" $true
    New-Candidate "Applications" "AutoHotkey scripts common folder" "%USERPROFILE%\Documents\AutoHotkey" "User scripts/hotkeys if stored in the conventional folder." "Add" $false
    New-Candidate "Applications" "PowerToys settings" "%LOCALAPPDATA%\Microsoft\PowerToys" "PowerToys modules/settings/key remaps." "Add" $false
    New-Candidate "Applications" "Sizer settings" "%APPDATA%\Sizer" "Custom window sizes/layouts if present." "Consider" $false
    New-Candidate "Applications" "Sandboxie Plus config" "%USERPROFILE%\Sandboxie-Plus.ini" "Sandbox definitions/settings if present." "Consider" $false
    New-Candidate "Applications" "Sandboxie config" "%WINDIR%\Sandboxie.ini" "System-wide sandbox definitions; requires admin to back up." "Manual" $false
