    New-Candidate "Android" "Android Studio settings" "%APPDATA%\Google\AndroidStudio*" "IDE settings/options. Wildcard is advisory; inspect manually." "Consider" $false
    New-Candidate "Android" "Android SDK" "%LOCALAPPDATA%\Android\Sdk" "Usually large/reinstallable; avoid except custom AVDs/system images." "Avoid" $false
    New-Candidate "Android" "Android AVDs" "%USERPROFILE%\.android\avd" "Custom emulator devices. Large opt-in." "Manual" $false

