    New-Candidate "Windows customization" "Explorer Advanced registry" "REG:HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "Explorer/taskbar preferences." "AlreadyCovered" $false
    New-Candidate "Windows customization" "Search registry" "REG:HKCU\Software\Microsoft\Windows\CurrentVersion\Search" "Search/Cortana/Bing preferences." "AlreadyCovered" $false
    New-Candidate "Windows customization" "User environment registry" "REG:HKCU\Environment" "User environment variables." "AlreadyCovered" $false
    New-Candidate "Windows customization" "Machine environment registry" "REG:HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\Environment" "Machine environment variables." "AlreadyCovered" $false
    New-Candidate "Windows customization" "Fonts installed by user" "%LOCALAPPDATA%\Microsoft\Windows\Fonts" "User-installed fonts. Avoid sharing font files publicly; backup privately if licensed." "Manual" $false
    New-Candidate "Windows customization" "Startup folder" "%APPDATA%\Microsoft\Windows\Start Menu\Programs\Startup" "Explicit per-user startup shortcuts/scripts." "Add" $false
