$results = @()

foreach ($c in $candidates) {
    $isRegistry = $c.Path.StartsWith("REG:")
    $expanded = if ($isRegistry) { $c.Path } else { Expand-CandidatePath $c.Path }
    $exists = $false
    $size = $null
    $lastWrite = $null
    $children = @()
    $coveredByScript = $false
    $coveredRaw = $null

    if ($isRegistry) {
        $regKey = $c.Path.Substring(4)
        $psRegPath = $regKey -replace '^HKCU\\','Registry::HKEY_CURRENT_USER\' -replace '^HKLM\\','Registry::HKEY_LOCAL_MACHINE\'
        $exists = Test-Path -LiteralPath $psRegPath
        $coveredByScript = ($covered.Keys | Where-Object { $_ -eq $expanded.ToLowerInvariant() }).Count -gt 0
    }
    elseif ($expanded -like '*`**' -or $expanded -like '*[*]*') {
        # Wildcard advisory item.
        $parent = Split-Path -Parent $expanded
        $leaf = Split-Path -Leaf $expanded
        if (Test-Path -LiteralPath $parent) {
            $matches = @(Get-ChildItem -LiteralPath $parent -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like $leaf })
            $exists = $matches.Count -gt 0
            $children = @($matches | Select-Object -First 10 | ForEach-Object { $_.FullName })
            $size = 0L
            foreach ($m in $matches) { $s = Get-DirectorySize -Path $m.FullName; if ($null -ne $s) { $size += $s } }
            $lastWrite = ($matches | Sort-Object LastWriteTime -Descending | Select-Object -First 1).LastWriteTime
        }
    }
    else {
        $exists = Test-Path -LiteralPath $expanded
        if ($exists) {
            $item = Get-Item -LiteralPath $expanded -Force -ErrorAction SilentlyContinue
            $lastWrite = $item.LastWriteTime
            $size = Get-DirectorySize -Path $expanded
            $children = Get-InterestingChildren -Path $expanded
        }

        $key = $expanded.TrimEnd('\').ToLowerInvariant()
        if ($covered.ContainsKey($key)) {
            $coveredByScript = $true
            $coveredRaw = $covered[$key]
        }
    }

    $large = ($null -ne $size -and $size -gt ($LargeThresholdMB * 1MB))
    $effectiveRecommendation = $c.Recommendation
    if ($coveredByScript -and $effectiveRecommendation -ne "Avoid") {
        $effectiveRecommendation = "AlreadyCovered"
    }
    elseif (-not $exists -and $effectiveRecommendation -eq "Add") {
        $effectiveRecommendation = "Consider"
    }
    elseif ($large -and $effectiveRecommendation -eq "Add") {
        $effectiveRecommendation = "Manual"
    }

    $results += [pscustomobject]@{
        Category = $c.Category
        Name = $c.Name
        Path = $c.Path
        ExpandedPath = $expanded
        Exists = $exists
        SizeBytes = $size
        Size = Format-Bytes $size
        LastWriteTime = $lastWrite
        Sensitive = $c.Sensitive
        Large = $large
        AlreadyCovered = $coveredByScript
        CoveredAs = $coveredRaw
        Recommendation = $effectiveRecommendation
        Why = $c.Why
        RestoreNote = $c.RestoreNote
        EvidenceHint = $c.EvidenceHint
        InterestingChildren = $children
    }
}

# Optional live inventories. These are metadata only.
$inventories = [ordered]@{}
if (Get-Command code.cmd -ErrorAction SilentlyContinue) {
    try { $inventories["VS Code extensions"] = @(& code.cmd --list-extensions 2>$null | Sort-Object) } catch {}
}
elseif (Get-Command code.exe -ErrorAction SilentlyContinue) {
    try { $inventories["VS Code extensions"] = @(& code.exe --list-extensions 2>$null | Sort-Object) } catch {}
}

if (Get-Command choco.exe -ErrorAction SilentlyContinue) {
    try { $inventories["Chocolatey packages"] = @(& choco.exe list --local-only 2>$null | Select-Object -First 200) } catch {}
}

if (Get-Command winget.exe -ErrorAction SilentlyContinue) {
    try { $inventories["Winget packages"] = @(& winget.exe list 2>$null | Select-Object -First 200) } catch {}
}

if (Get-Command wsl.exe -ErrorAction SilentlyContinue) {
    try { $inventories["WSL distros"] = @(& wsl.exe --list --verbose 2>$null) } catch {}
}

function Add-Line {
    param([System.Collections.Generic.List[string]]$Lines, [string]$Text = "")
    $Lines.Add($Text) | Out-Null
}

$lines = [System.Collections.Generic.List[string]]::new()
Add-Line $lines "# ChatGPT advisory: user-preference backup mining"
Add-Line $lines
Add-Line $lines "Generated: $(Get-Date -Format o)"
Add-Line $lines
Add-Line $lines "This report is based on path existence, sizes, timestamps, and selected filenames. It does **not** copy files and does **not** print secret contents."
Add-Line $lines
Add-Line $lines "## Summary"
Add-Line $lines
$found = @($results | Where-Object Exists)
$missing = @($results | Where-Object { -not $_.Exists })
$add = @($results | Where-Object { $_.Exists -and $_.Recommendation -eq "Add" })
$consider = @($results | Where-Object { $_.Exists -and $_.Recommendation -eq "Consider" })
$manual = @($results | Where-Object { $_.Exists -and $_.Recommendation -eq "Manual" })
$coveredFound = @($results | Where-Object { $_.Exists -and $_.AlreadyCovered })
$sensitiveFound = @($results | Where-Object { $_.Exists -and $_.Sensitive })
$largeFound = @($results | Where-Object { $_.Exists -and $_.Large })

Add-Line $lines "- Candidates checked: $($results.Count)"
Add-Line $lines "- Existing candidates: $($found.Count)"
Add-Line $lines "- Already covered by backup.ps1: $($coveredFound.Count)"
Add-Line $lines "- Recommended to add now: $($add.Count)"
Add-Line $lines "- Worth considering: $($consider.Count)"
Add-Line $lines "- Manual/large/special handling: $($manual.Count)"
Add-Line $lines "- Sensitive existing locations: $($sensitiveFound.Count)"
Add-Line $lines "- Large existing locations over $LargeThresholdMB MB: $($largeFound.Count)"
Add-Line $lines
Add-Line $lines "## Highest-value additions found"
Add-Line $lines
if ($add.Count -eq 0) {
    Add-Line $lines "No existing high-confidence additions were found."
} else {
    Add-Line $lines "| Category | Name | Path | Size | Sensitive | Why |"
    Add-Line $lines "|---|---|---|---:|:---:|---|"
    foreach ($r in ($add | Sort-Object Category, Name)) {
        Add-Line $lines ("| {0} | {1} | `{2}` | {3} | {4} | {5} |" -f
            (ConvertTo-MarkdownSafe $r.Category),
            (ConvertTo-MarkdownSafe $r.Name),
            (ConvertTo-MarkdownSafe $r.Path),
            $r.Size,
            ($(if ($r.Sensitive) { "yes" } else { "no" })),
            (ConvertTo-MarkdownSafe $r.Why)
        )
    }
}
Add-Line $lines

Add-Line $lines "## Consider / inspect before adding"
Add-Line $lines
if ($consider.Count -eq 0) {
    Add-Line $lines "No existing consider-level items were found."
} else {
    Add-Line $lines "| Category | Name | Path | Size | Sensitive | Why |"
    Add-Line $lines "|---|---|---|---:|:---:|---|"
    foreach ($r in ($consider | Sort-Object Category, Name)) {
        Add-Line $lines ("| {0} | {1} | `{2}` | {3} | {4} | {5} |" -f
            (ConvertTo-MarkdownSafe $r.Category),
            (ConvertTo-MarkdownSafe $r.Name),
            (ConvertTo-MarkdownSafe $r.Path),
            $r.Size,
            ($(if ($r.Sensitive) { "yes" } else { "no" })),
            (ConvertTo-MarkdownSafe $r.Why)
        )
    }
}
Add-Line $lines

Add-Line $lines "## Manual, large, or special-case items"
Add-Line $lines
if ($manual.Count -eq 0) {
    Add-Line $lines "No existing manual/special items were found."
} else {
    Add-Line $lines "| Category | Name | Path | Size | Sensitive | Restore note |"
    Add-Line $lines "|---|---|---|---:|:---:|---|"
    foreach ($r in ($manual | Sort-Object Category, Name)) {
        Add-Line $lines ("| {0} | {1} | `{2}` | {3} | {4} | {5} |" -f
            (ConvertTo-MarkdownSafe $r.Category),
            (ConvertTo-MarkdownSafe $r.Name),
            (ConvertTo-MarkdownSafe $r.Path),
            $r.Size,
            ($(if ($r.Sensitive) { "yes" } else { "no" })),
            (ConvertTo-MarkdownSafe $r.RestoreNote)
        )
    }
}
Add-Line $lines

Add-Line $lines "## Already covered and found"
Add-Line $lines
if ($coveredFound.Count -eq 0) {
    Add-Line $lines "No existing already-covered items were detected. Check BackupScriptPath if this is unexpected."
} else {
    Add-Line $lines "| Category | Name | Path | Size | Sensitive |"
    Add-Line $lines "|---|---|---|---:|:---:|"
    foreach ($r in ($coveredFound | Sort-Object Category, Name)) {
        Add-Line $lines ("| {0} | {1} | `{2}` | {3} | {4} |" -f
            (ConvertTo-MarkdownSafe $r.Category),
            (ConvertTo-MarkdownSafe $r.Name),
            (ConvertTo-MarkdownSafe $r.Path),
            $r.Size,
            ($(if ($r.Sensitive) { "yes" } else { "no" }))
        )
    }
}
Add-Line $lines

Add-Line $lines "## Detail by category"
Add-Line $lines
foreach ($cat in ($results.Category | Sort-Object -Unique)) {
    Add-Line $lines "### $cat"
    Add-Line $lines
    Add-Line $lines "| Status | Recommendation | Name | Path | Size | Last modified | Sensitive | Notes |"
    Add-Line $lines "|---|---|---|---|---:|---|:---:|---|"
    foreach ($r in ($results | Where-Object Category -eq $cat | Sort-Object Name)) {
        $status = if ($r.Exists) { "found" } else { "missing" }
        $last = if ($r.LastWriteTime) { $r.LastWriteTime.ToString("yyyy-MM-dd HH:mm") } else { "" }
        $notes = $r.Why
        if ($r.Large) { $notes += " Large: prefer opt-in/manual backup." }
        if ($r.AlreadyCovered) { $notes += " Already covered by backup.ps1." }
        Add-Line $lines ("| {0} | {1} | {2} | `{3}` | {4} | {5} | {6} | {7} |" -f
            $status,
            $r.Recommendation,
            (ConvertTo-MarkdownSafe $r.Name),
            (ConvertTo-MarkdownSafe $r.Path),
            $r.Size,
            $last,
            ($(if ($r.Sensitive) { "yes" } else { "no" })),
            (ConvertTo-MarkdownSafe $notes)
        )
    }
    Add-Line $lines
}

Add-Line $lines "## Interesting children from found directories"
Add-Line $lines
Add-Line $lines "This section lists names only, not contents. It helps distinguish custom preference files from caches."
Add-Line $lines
foreach ($r in ($found | Where-Object { $_.InterestingChildren.Count -gt 0 } | Sort-Object Category, Name)) {
    Add-Line $lines
    Add-Line $lines "### $($r.Name)"
    Add-Line $lines
    Add-Line $lines ('- Path: `' + (ConvertTo-MarkdownSafe $r.Path) + '`')
    Add-Line $lines "- Recommendation: $($r.Recommendation)"
    Add-Line $lines "- Children:"
    foreach ($child in $r.InterestingChildren) {
        if (-not $IncludeSensitiveDetails -and $r.Sensitive) {
            Add-Line $lines "  - [hidden because location is marked sensitive; rerun with -IncludeSensitiveDetails to show names only]"
            break
        }
        Add-Line $lines ('  - `' + (ConvertTo-MarkdownSafe $child) + '`')
    }
}
Add-Line $lines

Add-Line $lines "## Inventories"
Add-Line $lines
Add-Line $lines "These are useful for reconstruction and usually better than copying program folders."
foreach ($key in $inventories.Keys) {
    Add-Line $lines
    Add-Line $lines "### $key"
    Add-Line $lines
    if ($inventories[$key].Count -eq 0) {
        Add-Line $lines "No data captured."
    } else {
        Add-Line $lines '```text'
        foreach ($line in $inventories[$key]) {
            Add-Line $lines $line
        }
        Add-Line $lines '```'
    }
}

Add-Line $lines
Add-Line $lines "## Suggested backup.ps1 changes"
Add-Line $lines
Add-Line $lines "Review before applying. Sensitive paths should only go to encrypted backups."
Add-Line $lines
Add-Line $lines '```powershell'
foreach ($r in ($add | Sort-Object Category, Name)) {
    if ($r.Path.StartsWith("REG:")) { continue }
    Add-Line $lines ('Copy-BackupItem -Source "{0}" -RootName "user-preferences"' -f $r.Path)
}
Add-Line $lines '```'

Add-Line $lines
Add-Line $lines "## Suggested inventory commands"
Add-Line $lines
Add-Line $lines '```powershell'
Add-Line $lines 'New-Item -ItemType Directory -Force -Path "$env:USERPROFILE\dev-setup" | Out-Null'
Add-Line $lines 'if (Get-Command code -ErrorAction SilentlyContinue) { code --list-extensions | Sort-Object | Set-Content "$env:USERPROFILE\dev-setup\vscode-extensions.txt" -Encoding UTF8 }'
Add-Line $lines 'if (Get-Command pyenv -ErrorAction SilentlyContinue) { pyenv versions | Set-Content "$env:USERPROFILE\dev-setup\pyenv-versions.txt" -Encoding UTF8 }'
Add-Line $lines 'if (Get-Command pdm -ErrorAction SilentlyContinue) { pdm --version | Set-Content "$env:USERPROFILE\dev-setup\pdm-version.txt" -Encoding UTF8 }'
Add-Line $lines 'if (Get-Command gh -ErrorAction SilentlyContinue) { gh auth status 2>&1 | Set-Content "$env:USERPROFILE\dev-setup\gh-auth-status.txt" -Encoding UTF8 }'
Add-Line $lines '```'

Add-Line $lines
Add-Line $lines "## Caution"
Add-Line $lines
Add-Line $lines "- Do not upload this report publicly if `-IncludeSensitiveDetails` was used."
Add-Line $lines "- Backups containing SSH, cloud CLI, rclone, Docker, database, VPN, WinAuth, or AI assistant auth state should be encrypted."
Add-Line $lines "- Avoid restoring large app state blindly across Windows versions; prefer explicit import/export when available."

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $OutputPath) | Out-Null
$lines | Set-Content -LiteralPath $OutputPath -Encoding UTF8

Write-Host "Wrote advisory: $OutputPath"
Write-Host "Found $($found.Count) existing candidates; $($add.Count) high-confidence additions; $($consider.Count) consider-level items."
